static boolean init_system_port(const char* component_type, const char* port_name)
{
if (!strcmp(component_type, "SECCTester")) {
if (!strcmp(port_name, "pt_V2G_TCP_TLS_ALM_SECC_Port")) {
SECCTester_component_pt__V2G__TCP__TLS__ALM__SECC__Port.safe_start();
return TRUE;
}
if (!strcmp(port_name, "pt_V2G_UDP_SDP_Port")) {
SECCTester_component_pt__V2G__UDP__SDP__Port.safe_start();
return TRUE;
}
}
else if (!strcmp(component_type, "SystemSECC")) {
if (!strcmp(port_name, "pt_V2G_TCP_TLS_ALM_SECC_Port")) {
SystemSECC_component_pt__V2G__TCP__TLS__ALM__SECC__Port.safe_start();
return TRUE;
}
if (!strcmp(port_name, "pt_V2G_UDP_SDP_Port")) {
SystemSECC_component_pt__V2G__UDP__SDP__Port.safe_start();
return TRUE;
}
}
return FALSE;
}


